h1_32 = shP(0.28, 0, 'h'); h2_32 = shP(1.0, 60, 'h'); h3_32 = sT(30, 'hf'); QH32 = 60000 / 3600; m32 = QH32 / (h2_32 - h3_32); W32 = m32 * (h2_32 - h1_32); QL32 = m32 * (h1_32 - h3_32); Wres = QH32 - W32
